const db = { load() { const current = JSON.parse(localStorage.getItem('mtj-db') || 'null'); if (current?.exhibitions) return normalize(current); const legacy = JSON.parse(localStorage.getItem('mtj-exhibitions') || 'null'); return normalize(legacy ? { exhibitions: legacy, collections: defaultCollections } : defaults); }, save() { const compact = { collections: store.collections, exhibitions: store.exhibitions.map(exhibition => ({ ...exhibition, artworks: exhibition.artworks.map(artwork => { const { originalImage, captionImage, ...keep } = artwork; return keep; }) })) }; localStorage.removeItem('mtj-exhibitions'); try { localStorage.setItem('mtj-db', JSON.stringify(compact)); } catch (error) { localStorage.removeItem('mtj-db'); localStorage.setItem('mtj-db', JSON.stringify({ collections: store.collections, exhibitions: store.exhibitions.map(exhibition => ({ ...exhibition, artworks: exhibition.artworks.map(artwork => ({ ...artwork, originalImage: undefined, captionImage: undefined, captionCrop: undefined })) })) })); } } };
