function exhibitionCard(e) { return `<article class="exhibition-card" data-exhibition="${e.id}"><div class="cover-wrap">${e.cover ? `<img src="${e.cover}" alt="${escapeHtml(e.name)} cover">` : '<div class="cover-placeholder">No cover image</div>'}<div class="cover-gradient"></div><span class="card-badge">${icon('bookmark')}${escapeHtml(e.collection || 'Unsorted')}</span></div><div class="card-body"><h3 class="card-title">${escapeHtml(e.name)}</h3><div class="card-meta"><span>${icon('pin')}${escapeHtml(e.museum)}</span><span>${formatDate(e.date)}</span></div><div class="card-artists"><span>${e.artworks.length} artworks ${icon('arrow')}</span></div></div></article>`; }
