function bindTabEvents(a) { document.querySelectorAll('#tab-content [data-action]').forEach(button => button.addEventListener('click', () => { if (button.dataset.action === 'new-note') openNoteModal(a); if (button.dataset.action === 'scan-caption') openCaptionPicker(a); if (button.dataset.action === 'review-caption') openCaptionEditor(a); if (button.dataset.action === 'edit-artwork') openArtworkEditor(a); })); document.querySelectorAll('#tab-content [data-edit-note]').forEach(button => button.addEventListener('click', () => openNoteModal(a, Number(button.dataset.editNote)))); }
function openNoteModal(a, noteIndex = -1) {
  const note = a.notes?.[noteIndex]; showModal(`<div class="modal-header"><div><div class="eyebrow">${note ? 'Edit note' : 'New note'}</div><h2>What stayed with you?</h2><p>Keep the immediate thought, the question, or the thread to follow later.</p></div><button class="close" aria-label="Close" data-close>${icons.close}</button></div><form id="note-form"><div class="field"><label for="note-text">Your note</label><textarea id="note-text" required placeholder="Write a thought...">${note ? escapeHtml(note.text) : ''}</textarea></div><div class="field"><label>Tags</label><div class="tag-picker">${['Research', 'My thoughts', 'Links'].map(tag => `<label><input type="checkbox" value="${tag}" ${note?.tags?.includes(tag) ? 'checked' : ''}> ${tag}</label>`).join('')}</div></div><div class="form-footer"><button type="button" class="secondary" data-close>Cancel</button><button class="primary" type="submit">Save note</button></div></form>`);
  document.querySelector('#note-form').addEventListener('submit', event => { event.preventDefault(); const tags = [...document.querySelectorAll('#note-form input:checked')].map(input => input.value); const item = { text: document.querySelector('#note-text').value.trim(), tags, createdAt: 'Just now' }; a.notes = a.notes || []; if (noteIndex >= 0) a.notes[noteIndex] = item; else a.notes.unshift(item); save(); closeModal(); openArtwork(a.id); toast('Note saved'); });
}
function openCaptionPicker(a) {
  showModal(`<div class="modal-header"><div><div class="eyebrow">Caption scan</div><h2>Photograph the label.</h2><p>Choose a caption photo. English, Chinese, and Japanese text are supported when OCR is available.</p></div><button class="close" aria-label="Close" data-close>${icons.close}</button></div><div class="dropzone upload-zone">${icon('upload')}<div><strong>Select a caption photo</strong><span>The original image will stay attached to this artwork</span></div><button type="button" class="primary" id="caption-choose">Choose photo</button></div><input id="caption-file" class="hidden" type="file" accept="image/*" capture="environment"><div class="form-footer"><button type="button" class="secondary" data-close>Cancel</button></div>`);
  document.querySelector('#caption-choose').addEventListener('click', () => document.querySelector('#caption-file').click()); document.querySelector('#caption-file').addEventListener('change', async event => { const file = event.target.files[0]; if (file) { const original = await readDataUrl(file); openCropper(file, 'Crop caption for scanning', cropped => scanCaption(a, cropped, file.name, original)); } });
}
async function scanCaption(a, croppedImage, originalName, originalImage) {
  toast('Scanning caption…'); a.captionImage = originalImage; a.captionCrop = croppedImage; let text = '';
  try { if (window.Tesseract) { const result = await Tesseract.recognize(croppedImage, 'eng+chi_sim+jpn'); text = result.data.text.trim(); } } catch (error) { console.warn('OCR unavailable; using editable fallback', error); }
  a.caption = text || `Caption captured from ${originalName}. Edit this text to confirm the reading.`; save(); closeModal(); openArtwork(a.id); toast(text ? 'Caption scanned — please review the text' : 'Caption photo attached — text is ready to edit');
}
function openCaptionEditor(a) { showModal(`<div class="modal-header"><div><div class="eyebrow">OCR review</div><h2>Check the details.</h2><p>Make corrections before saving.</p></div><button class="close" aria-label="Close" data-close>${icons.close}</button></div><div class="field"><label for="caption-text">Extracted caption</label><textarea id="caption-text" style="min-height:135px">${escapeHtml(a.caption || '')}</textarea></div><div class="form-footer"><button type="button" class="secondary" data-close>Cancel</button><button type="button" class="primary" id="save-caption">Save caption</button></div>`); document.querySelector('#save-caption').addEventListener('click', () => { a.caption = document.querySelector('#caption-text').value.trim(); save(); closeModal(); openArtwork(a.id); toast('Caption saved'); }); }
function openArtworkEditor(a) { showModal(`<div class="modal-header"><div><div class="eyebrow">Artwork metadata</div><h2>Edit artwork</h2></div><button class="close" aria-label="Close" data-close>${icons.close}</button></div><form id="artwork-form"><div class="field"><label for="art-title">Title</label><input id="art-title" value="${escapeHtml(a.title)}"></div><div class="field-row"><div class="field"><label for="art-artist">Artist</label><input id="art-artist" value="${escapeHtml(a.artist)}"></div><div class="field"><label for="art-year">Year</label><input id="art-year" value="${escapeHtml(a.year)}"></div></div><div class="field-row"><div class="field"><label for="art-medium">Medium</label><input id="art-medium" value="${escapeHtml(a.medium)}"></div><div class="field"><label for="art-location">Museum location</label><input id="art-location" value="${escapeHtml(a.location)}"></div></div><div class="form-footer"><button type="button" class="secondary" data-close>Cancel</button><button class="primary" type="submit">Save metadata</button></div></form>`); document.querySelector('#artwork-form').addEventListener('submit', event => { event.preventDefault(); a.title = document.querySelector('#art-title').value.trim(); a.artist = document.querySelector('#art-artist').value.trim(); a.year = document.querySelector('#art-year').value.trim(); a.medium = document.querySelector('#art-medium').value.trim(); a.location = document.querySelector('#art-location').value.trim(); save(); closeModal(); openArtwork(a.id); toast('Artwork metadata saved'); }); }
function confirmDelete(type) {
  const a = type === 'artwork' ? getArtwork(state.modalArtworkId) : null; const label = type === 'exhibition' ? getExhibition().name : a?.title;
  showModal(`<div class="modal-header"><div><div class="eyebrow">This cannot be undone</div><h2>Delete ${type}?</h2><p>${escapeHtml(label || 'This record')} will be removed from your local journal.</p></div><button class="close" aria-label="Close" data-close>${icons.close}</button></div><div class="form-footer"><button class="secondary" data-close>Keep it</button><button class="danger" id="confirm-delete">${icon('trash')} Delete ${type}</button></div>`);
  document.querySelector('#confirm-delete').addEventListener('click', () => { if (type === 'exhibition') { store.exhibitions = store.exhibitions.filter(e => e.id !== state.selectedId); state.view = 'home'; state.selectedId = null; } else { const e = getExhibition(); e.artworks = e.artworks.filter(x => x.id !== a.id); state.modalArtworkId = null; } save(); closeModal(); render(); toast(`${type[0].toUpperCase() + type.slice(1)} deleted`); });
}
function bindWallInteractions() {
  const wall = document.querySelector('.wall.editing'); if (!wall) return;
  wall.addEventListener('pointerdown', event => { const card = event.target.closest('.art-card'); if (!card || event.target.closest('[data-action]')) return; const a = getArtwork(Number(card.dataset.artwork)); const rect = wall.getBoundingClientRect(); const layout = a.layout || defaultLayout([...wall.querySelectorAll('.art-card')].indexOf(card)); const resizing = event.target.closest('.resize-handle'); const startX = event.clientX; const startY = event.clientY; const start = { ...layout }; let moved = false; card.setPointerCapture(event.pointerId);
    const move = moveEvent => { const dx = (moveEvent.clientX - startX) / rect.width * 100; const dy = (moveEvent.clientY - startY) / rect.height * 100; moved = moved || Math.abs(dx) > 1 || Math.abs(dy) > 1; a.layout = resizing ? { ...start, width: Math.max(16, Math.min(50, start.width + dx)), height: Math.max(18, Math.min(50, start.height + dy)) } : { ...start, left: Math.max(0, Math.min(100 - start.width, start.left + dx)), top: Math.max(0, Math.min(100 - start.height, start.top + dy)) }; card.style.left = `${a.layout.left}%`; card.style.top = `${a.layout.top}%`; card.style.width = `${a.layout.width}%`; card.style.height = `${a.layout.height}%`; };
    const up = () => { card.removeEventListener('pointermove', move); card.removeEventListener('pointerup', up); if (moved) card.dataset.dragged = 'yes'; save(); }; card.addEventListener('pointermove', move); card.addEventListener('pointerup', up);
  });
}
function showModal(content) { const root = document.querySelector('#modal-root'); root.innerHTML = `<div class="modal-backdrop show"><div class="modal">${content}</div></div>`; root.querySelectorAll('[data-close]').forEach(button => button.addEventListener('click', closeModal)); root.querySelector('.modal-backdrop').addEventListener('click', event => { if (event.target.classList.contains('modal-backdrop')) closeModal(); }); root.querySelectorAll('[data-action="delete-artwork"]').forEach(button => button.addEventListener('click', () => confirmDelete('artwork'))); }
function closeModal() { const root = document.querySelector('#modal-root'); if (root) root.innerHTML = ''; }
render();
